/*
 * POP QUIZ PARTY — CATEGORY BLITZ PROMPT BANK
 * ===========================================
 * Edit freely! Each line is one prompt for its category (the section it's in):
 *
 *   p("S", "easy", "The Simpsons | Seinfeld | SpongeBob SquarePants / SpongeBob | ...")
 *   p("D", "hard", "Daria | ...", "pg13")
 *     letter difficulty  accepted answers                                      content (default "clean")
 *
 * - Answers are separated by "|". Alternate spellings or names for the SAME answer
 *   go in one group, separated by " / " (with spaces): they count as one answer
 *   for uniqueness, e.g. "Saturday Night Live / SNL".
 * - Every answer must start with the letter once a leading "The/A/An" is dropped
 *   ("The Simpsons" is an S answer; "The Office" would be an O answer).
 * - Players don't need to type exactly: case, accents, punctuation, extra spaces
 *   and a leading "the/a/an" are ignored; 1 typo is forgiven for 5–8 letters and
 *   2 for longer answers. Shorter answers must be exact. Close but different
 *   answers (Mouse / Moose, Niger / Nigeria) are never merged.
 * - difficulty: "easy" | "medium" | "hard". content "pg13" prompts only appear in PG-13 games.
 * - `npm test` checks the file: 15+ prompts per category, one prompt per letter,
 *   30+ answers each, every answer starts with the letter, no duplicates, and
 *   Clean prompts pass the Clean content filter.
 * - Answers that aren't listed go to the host to approve or reject after each round.
 */
import "server-only";
import type { BlitzPromptEntry, BuiltInBlitzCategoryId, ContentLevel, Difficulty } from "@/lib/game/types";

function p(letter: string, difficulty: Difficulty, answers: string, content: ContentLevel = "clean"): BlitzPromptEntry {
  return {
    letter,
    difficulty,
    content,
    answers: answers
      .split("|")
      .map((group) => group.split(" / ").map((a) => a.trim()).filter(Boolean))
      .filter((g) => g.length > 0),
  };
}

